    CountDownLatch ready = new CountDownLatch(2);
    CountDownLatch start = new CountDownLatch(1);
    AtomicInteger success = new AtomicInteger();
    Future<Outcome> futureA = executor.submit(() -> runTagged(taskA, ready, start, success));
    Future<Outcome> futureB = executor.submit(() -> runTagged(taskB, ready, start, success));
    assertThat(ready.await(10, TimeUnit.SECONDS)).isTrue();
    start.countDown();
    Outcome a = futureA.get(30, TimeUnit.SECONDS);
    Outcome b = futureB.get(30, TimeUnit.SECONDS);
    return List.of(a, b);
}

private Outcome runTagged(Runnable task, CountDownLatch ready, CountDownLatch start,
                          AtomicInteger ignored) {
    try {
        ready.countDown();
        start.await(10, TimeUnit.SECONDS);
        task.run();
        return new Outcome(null, null);
    } catch (Throwable t) {
        return new Outcome(null, t);
    }
}

